%{
#include <stdio.h>
#include <stdlib.h>
#include "calc.h"
#include "calc.tab.h"
%}
%option noyywrap

%%
[0-9]+(\.[0-9]+)?  { yylval.number = atof(yytext); return NUMBER; }
"+"                { return ADD; }
"-"                { return SUBTRACT; }
"*"                { return MULTIPLY; }
"/"                { return DIVIDE; }
"("                { return LPAREN; }
")"                { return RPAREN; }
\n                 { return '\n'; }
[ \t]+             { /* skip */ }
.                  { fprintf(stderr, "Unexpected character: %s\n", yytext); exit(1); }
%%
